mapper.sql:
FROM bike_dispatch_notification n
LEFT JOIN bike_dispatch_notification_read r ON r.notification_id = n.id AND r.user_id = #{audience.userId}
WHERE (
  (#{audience.orderAllowed} = TRUE AND n.kind = 'ORDER')
  OR (#{audience.piAllowed} = TRUE AND n.kind = 'PI')
)

  AND EXISTS (
    SELECT 1 FROM bike_user_customer_scope cs
    WHERE cs.user_id = #{audience.customerScopeUserId} AND cs.customer_id = n.customer_id
  )
